#!/usr/bin/env bash
# Question 1: Errors across replicas. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/logs
mkdir -p /opt/course/logs
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q1_NS}" delete deployment checkout --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q1_NS}" apply -f - <<'EOF' >/dev/null
apiVersion: apps/v1
kind: Deployment
metadata:
  name: checkout
spec:
  replicas: 3
  selector:
    matchLabels: { app: checkout }
  template:
    metadata:
      labels: { app: checkout }
    spec:
      terminationGracePeriodSeconds: 1
      containers:
        - name: api
          image: busybox:1.36
          command:
            - sh
            - -c
            - |
              errors=$(( $(od -An -N1 -tu1 /dev/urandom) % 20 + 4 ))
              i=0
              while [ $i -lt 60 ]; do
                echo "INFO request $i handled in $(( i % 7 + 3 ))ms"
                if [ $i -lt $errors ]; then echo "ERROR payment gateway timeout on request $i"; fi
                i=$(( i + 1 ))
              done
              sleep infinity
        - name: proxy
          image: busybox:1.36
          command: ["sh", "-c", "echo 'ERROR proxy upstream api not ready yet'; echo 'INFO proxy listening on 8080'; sleep infinity"]
EOF
kubectl -n "${Q1_NS}" rollout status deployment/checkout --timeout=180s >/dev/null
: "${Q1_NS}"
